NOTE=' Screenshots are not reproduced; each screenshot is redrawn as simplified coded SVG with the legible printed labels. Watermark, border lines, page-edge shadows and handwriting are excluded.'
def fin(s,note):
    s['sourceNote']=note+NOTE; s['vocabulary']={}; save(s)
def shell(w,h,title,body,label):
    b=f'<rect x="5" y="5" width="{w-10}" height="{h-10}" fill="#f4f7fb" stroke="#555"/><rect x="5" y="5" width="{w-10}" height="16" fill="#cfd9ea" stroke="#555"/>'+T(w/2,17,title,8,'middle',400)
    return svg(w,h,label,b+body)
def ribbon(tabs,y=30):
    b='<circle cx="22" cy="%d" r="8" fill="#d9b04a" stroke="#555"/>'%(y+5)
    for k,t in enumerate(tabs): b+=T(45+k*68,y+9,t,8,'start',700)
    return b+f'<rect x="10" y="{y+16}" width="420" height="36" fill="#e8eef8" stroke="#aaa"/>'
def stud(sub=False):
    body=ribbon(['Home','Create','External Data','Database Tools','Datasheet'])+'<rect x="10" y="95" width="100" height="95" fill="#fff" stroke="#888"/>'+T(15,108,'All Tables',8,'start',700)+T(15,124,'Student',8,'start',700)+T(30,136,'Student : Table',8,'start',400)+T(15,150,'Exam',8,'start',700)+T(30,162,'Exam : Table',8,'start',400)
    body+='<rect x="115" y="95" width="315" height="95" fill="#fff" stroke="#888"/>'+T(125,107,'Roll No',8,'start',700)+T(180,107,'St Name',8,'start',700)+T(260,107,'Class',8,'start',700)+T(320,107,'Section',8,'start',700)+T(380,107,'Add New Field',8,'start',700)
    rows=[('1','Ahmed','XI','B'),('2','Tahir','XI','B'),('3','Danish','XI','B'),('4','Zubair','XI','B'),('5','Umer','XI','C')]
    for k,r in enumerate(rows):
        for j,x in enumerate((125,180,260,320)): body+=T(x,121+k*11,r[j],7,'start',400)
    if sub: body+='<rect x="140" y="124" width="180" height="32" fill="#fff" stroke="#555"/>'+T(145,133,'Exam ID   Exam Type   Marks obtained',6,'start',700)+T(145,143,'1  First Term   450',6,'start',400)+T(145,153,'2  Second Term   470',6,'start',400)
    return body
